"""Bounded, single-threaded chronological direct seven-horizon study."""
import datetime as dt, hashlib, json, os, platform, resource, time
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[1]
SEED=41010
VERSION='dormathon.sales-engine.0.4.1'
FEATURES=['intercept','lag_1','lag_7','lag_14','lag_28','mean_7','mean_28','std_28','nonzero_rate_28']+['target_dow_'+str(i) for i in range(6)]
def write(path,value):
 tmp=path.with_suffix(path.suffix+'.tmp');tmp.write_text(json.dumps(value,indent=2,ensure_ascii=False,allow_nan=False));tmp.replace(path)
def features(y,origins,h,means,dates):
 o=np.array(origins);a=[np.ones((len(y),len(o)))];s=means[:,None]
 for lag in [1,7,14,28]:a.append(y[:,o-lag+1]/s)
 hist=np.stack([y[:,o-k] for k in range(28)],axis=-1)
 a.extend([hist[:,:,:7].mean(axis=-1)/s,hist.mean(axis=-1)/s,hist.std(axis=-1)/s,(hist>0).mean(axis=-1)])
 dow=np.array([dt.date.fromisoformat(str(dates[x+h])).weekday() for x in o])
 for d in range(6):a.append(np.broadcast_to(dow==d,(len(y),len(o))))
 return np.stack(a,axis=-1).astype(np.float64)
def baseline(y,origins):
 o=np.array(origins);seas=np.stack([y[:,o+h-7] for h in range(1,8)],axis=-1);ma=np.stack([y[:,o-k] for k in range(28)],axis=-1).mean(axis=-1)
 return {'seasonal_naive_7':seas,'moving_average_28':np.repeat(ma[:,:,None],7,axis=-1)}
def ridge(y,origins,means,dates,coef):
 return np.stack([np.maximum(0,np.einsum('ijk,k->ij',features(y,origins,h,means,dates),coef[h-1]))*means[:,None] for h in range(1,8)],axis=-1)
def actual(y,origins):return np.stack([y[:,np.array(origins)+h] for h in range(1,8)],axis=-1)
def metrics(pred,act,scales):
 err=np.abs(pred-act);total=float(act.sum());nz=scales>0
 return {'prediction_points':int(act.size),'item_count':len(act),'origins_per_item':act.shape[1],'MAE_units':float(err.mean()),'WAPE':float(err.sum()/total) if total>0 else None,'WAPE_denominator_actual_units':total,'WAPE_zero_denominator_handling':'null; no averaging item-level percentage errors','MASE_seasonal_7':float((err[nz]/scales[nz,None,None]).mean()) if nz.any() else None,'MASE_scaling_items':int(nz.sum()),'MASE_undefined_items':int((~nz).sum()),'zero_actual_prediction_points':int((act==0).sum()),'mean_prediction_units':float(pred.mean()),'horizon_metrics':[{'horizon':h+1,'MAE_units':float(err[:,:,h].mean()),'WAPE':float(err[:,:,h].sum()/act[:,:,h].sum()) if act[:,:,h].sum()>0 else None,'actual_units':float(act[:,:,h].sum())} for h in range(7)]}
def paired(candidate,base,act,seed=SEED,nboot=400):
 dif=(np.abs(candidate-act)-np.abs(base-act)).sum(axis=-1);den=act.sum(axis=-1);rng=np.random.default_rng(seed);n,m=dif.shape;blocks=[np.arange(k,min(m,k+7)) for k in range(0,m,7)];vals=[]
 for _ in range(nboot):
  ids=rng.integers(0,n,n);cols=np.concatenate([blocks[b] for b in rng.integers(0,len(blocks),len(blocks))]);d=dif[np.ix_(ids,cols)];v=den[np.ix_(ids,cols)].sum();vals.append((float(d.mean()/7),float(d.sum()/v) if v else 0))
 vals=np.array(vals)
 return {'candidate_minus_baseline_MAE_units':float(dif.mean()/7),'candidate_minus_baseline_WAPE':float(dif.sum()/den.sum()) if den.sum()>0 else None,'MAE_95pct_interval':np.quantile(vals[:,0],[.025,.975]).tolist(),'WAPE_95pct_interval':np.quantile(vals[:,1],[.025,.975]).tolist(),'uncertainty_method':'two-way cluster bootstrap: resample known SKU groups and nonoverlapping seven-origin time blocks (last block partial); each selected block retains all 7 overlapping forecast horizons','replicates':nboot,'seed':seed,'origin_blocks':len(blocks),'limitations':'Four short time blocks and related retailer SKUs limit inference; descriptive dependence-aware uncertainty, not cross-company evidence.'}
def run():
 t=time.monotonic();config=json.loads((ROOT/'config.json').read_text());assert config['seed']==SEED and config['horizon_days']==7 and config['test_days']==28 and config['validation_days']==28 and config['minimum_nonzero_train_days']==26 and config['ridge_alpha_candidates']==[10,100,1000], 'Frozen evaluation scope/configuration changed; explicit new study required.';d=np.load(ROOT/'data/derived/daily-sales.npz',allow_pickle=False);p=json.loads((ROOT/'artifacts/data-profile.v1.json').read_text());split=p['split'];y=d['sales'][d['eligible']].astype(np.float64);returns=d['returns'][d['eligible']].astype(np.float64);duplicate_y=d['with_duplicates'][d['eligible']].astype(np.float64);dates=d['dates'];items=d['items'][d['eligible']];n=y.shape[1];cut=n-56;means=np.maximum(1,y[:,:cut].mean(axis=1));scales=np.abs(y[:,7:cut]-y[:,:cut-7]).mean(axis=1);val_orig=list(range(cut-1,n-28-7));test_orig=list(range(n-29,n-7));vact=actual(y,val_orig);tact=actual(y,test_orig);vp=baseline(y,val_orig);tp=baseline(y,test_orig)
 base_report={'schema_version':'dormathon.predictive.v1','engine_version':VERSION,'org_id':'external_uci_online_retail_ii','brand_scope':'Original single UK non-store retailer, 2009–2011','scenarioDataMode':'EXTERNAL_BENCHMARK','status':'partial','delivery_mode':'precomputed','target_definition':'Daily positive item transaction sales, units, seven daily horizons; observed-sales demand proxy, not latent demand','generated_at':dt.datetime.now(dt.timezone.utc).isoformat(),'provenance':p['source'],'split':split,'sample_sizes':{'eligible_items':len(y),'excluded_items':split['excluded_item_count'],'training_calendar_days':cut,'validation_origins_per_item':len(val_orig),'test_origins_per_item':len(test_orig),'test_prediction_points':tact.size,'unique_test_item_days':len(y)*28,'overlap_note':'22 daily origins x 7 horizon predictions; repeated target observations are separate forecast tasks, not independent outcomes'},'models':{k:{'version':VERSION+':'+k,'validation':metrics(v,vact,scales),'test':metrics(tp[k],tact,scales)} for k,v in vp.items()},'gates':{'AC11':{'status':'pass_with_declared_assumption','reason':'Official licensed bytes profiled; target, train-only eligible SKU catalog, full calendar split and incomplete trailing day frozen; interior zero dates rely on publisher complete-ledger declaration.'},'AC12':{'status':'pending','reason':'Baselines evaluated; bounded lag/calendar candidate, paired uncertainty and sensitivity still running.'}},'limitations':['No empirical MR D.I.Y. accuracy claim; synthetic company mechanics are separate.','No inventory, lead-time, stockout, delivery or operating-cost ground truth.','Known-item temporal evaluation only; cold-start and cross-company performance not established.','Retrospective transaction-time availability assumption; historical system-known replay and late-update logs unavailable.','Complete-ledger observation scope is source-declared, not independently audited; missing SKU-day zeros mean zero recorded positive sales, never latent demand.'],'warnings':['Point forecasts only: calibrated prediction intervals are not produced.'],'uncertainty':None}
 write(ROOT/'artifacts/benchmark-report.v1.json',base_report);print('BASELINES_READY',json.dumps({k:base_report['models'][k]['test'] for k in tp}),flush=True)
 # Compact fixed direct ridge; all labels <= train cutoff, 7-day stride for bounded resources.
 train_orig=list(range(27,cut-7,7));coefs={alpha:[] for alpha in [10.,100.,1000.]}
 for h in range(1,8):
  X=features(y,train_orig,h,means,dates).reshape(-1,len(FEATURES));z=(y[:,np.array(train_orig)+h]/means[:,None]).reshape(-1);A=X.T@X;b=X.T@z
  for alpha in coefs:
   penalty=np.eye(len(FEATURES))*alpha;penalty[0,0]=0;coefs[alpha].append(np.linalg.solve(A+penalty,b))
  del X,z,A,b
 validation_candidates={a:ridge(y,val_orig,means,dates,np.array(c)) for a,c in coefs.items()};val_scores={str(a):metrics(z,vact,scales)['WAPE'] for a,z in validation_candidates.items()};best_alpha=min(coefs,key=lambda a:val_scores[str(a)]);coef=np.array(coefs[best_alpha]);vp['ridge_lag_calendar']=validation_candidates[best_alpha];tp['ridge_lag_calendar']=ridge(y,test_orig,means,dates,coef)
 models={k:{'version':VERSION+':'+k,'validation':metrics(v,vact,scales),'test':metrics(tp[k],tact,scales)} for k,v in vp.items()};comparisons={k:paired(tp['ridge_lag_calendar'],tp[k],tact) for k in ['seasonal_naive_7','moving_average_28']};validation_winner=min(models,key=lambda k:models[k]['validation']['WAPE']);best_base=min(['seasonal_naive_7','moving_average_28'],key=lambda k:models[k]['validation']['WAPE']);supported=comparisons[best_base]['WAPE_95pct_interval'][1]<0;selected=validation_winner if validation_winner!='ridge_lag_calendar' or supported else best_base
 # Fixed training-only volume and sparsity strata; no test exclusion for inactive SKUs.
 rawmeans=y[:,:cut].mean(axis=1);qs=np.quantile(rawmeans,[.25,.5,.75]);ng=(y[:,:cut]>0).mean(axis=1);grouping={'volume':{'low':rawmeans<=qs[0],'medium_low':(rawmeans>qs[0])&(rawmeans<=qs[1]),'medium_high':(rawmeans>qs[1])&(rawmeans<=qs[2]),'high':rawmeans>qs[2]},'sparsity':{'sparse_lt25pct':ng<.25,'intermittent_25to50pct':(ng>=.25)&(ng<.5),'frequent_ge50pct':ng>=.5},'failure':{'test_zero_volume':tact.sum(axis=(1,2))==0}}
 slices={kind:{name:{'item_count':int(mask.sum()),'models':{k:metrics(z[mask],tact[mask],scales[mask]) for k,z in tp.items()} if mask.any() else {}} for name,mask in gs.items()} for kind,gs in grouping.items()}
 # Sensitivities use immutable catalog/model: no test-informed refits or population changes.
 sensitivity={'exact_duplicates_retained':{k:metrics(z,actual(duplicate_y,test_orig),scales) for k,z in tp.items()},'returns_subtracted_label_diagnostic':{'target_changed':True,'not_primary_metric':True,'label':'net unit movement = positive sales - absolute return/cancellation units; may be negative and does not recover latent demand','models':{k:metrics(z,actual(y-returns,test_orig),scales) for k,z in tp.items()}}}
 longgaps={a for run in p['coverage']['consecutive_transaction_free_runs'] if len(run)>=3 for a in run};good=np.array([not any(str(dates[o+h]) in longgaps for h in range(1,8)) for o in test_orig]);sensitivity['exclude_forecasts_touching_long_global_gap']={'excluded_dates':sorted(longgaps),'threshold_consecutive_days':3,'retained_origins':int(good.sum()),'all_origins':len(good),'models':{k:metrics(z[:,good,:],tact[:,good,:],scales) for k,z in tp.items()} if good.any() else None}
 rng=np.random.default_rng(SEED);noise_y=np.maximum(0,np.rint(y*(1+rng.normal(0,.1,y.shape))));npred=baseline(noise_y,test_orig);npred['ridge_lag_calendar']=ridge(noise_y,test_orig,means,dates,coef);sensitivity['history_quantity_noise']={'seed':SEED,'standard_deviation_fraction':.1,'mechanism':'multiplicative Gaussian perturbation, round to whole units and clamp nonnegative; only inputs through each origin affect forecast, labels remain original','models':{k:metrics(z,tact,scales) for k,z in npred.items()}}
 missing_rng=np.random.default_rng(SEED+1);mask=missing_rng.random(y.shape)<.02;safe=np.array([[not mask[i,o-27:o+1].any() for o in test_orig] for i in range(len(y))]);sensitivity['missing_history_abstention']={'missing_probability':.02,'seed':SEED+1,'mechanism':'unknown history date blocks a 28-day forecast; no missing-value zero fill','origin_item_requests':int(safe.size),'abstained_requests':int((~safe).sum()),'available_requests':int(safe.sum()),'forecast_metrics_conditional_on_available_requests':{k:{'MAE_units':float(np.abs(z-tact)[safe].mean()),'WAPE':float(np.abs(z-tact)[safe].sum()/tact[safe].sum()) if tact[safe].sum()>0 else None} for k,z in tp.items()}}
 manifest={'engine_version':VERSION,'seed':SEED,'features':FEATURES,'feature_policy':'only origin-and-earlier sales lags/rolling summaries; future target weekday is deterministic calendar, no external news or future realized values','candidate':'pooled scale-normalized direct ridge, 7 separate linear horizons, nonnegative point output','training_samples_per_horizon':len(y)*len(train_orig),'train_origin_stride_days':7,'normalization':'per-SKU training-only mean bounded below 1; no test preprocessing','ridge_alpha_candidates':[10,100,1000],'validation_WAPE_by_alpha':val_scores,'chosen_alpha':best_alpha,'coefficients':coef.tolist(),'training_item_scale':dict(zip(items.tolist(),means.tolist())),'model_version':VERSION+':ridge_lag_calendar','split_configuration_sha256':split['configuration_sha256'],'model_selection_policy':'alpha and winner selected on validation WAPE only; candidate retained for recommended use only if paired test uncertainty against validation-best baseline supports improvement; otherwise retain validation-best baseline','returns_and_duplicates_rule_frozen_before_test':True,'uncertainty_seed':SEED,'point_only':True}
 write(ROOT/'artifacts/model-artifact.v1.json',manifest)
 base_report.update(status='ok',generated_at=dt.datetime.now(dt.timezone.utc).isoformat(),models=models,selected_model=selected,selection={'validation_winner':validation_winner,'validation_best_baseline':best_base,'candidate_test_superiority_supported_vs_best_baseline':supported,'reason':'Validation winner retained with disclosed test evidence' if selected==validation_winner else 'Candidate superiority not supported; retain validation-best baseline'},paired_comparisons=comparisons,slices=slices,sensitivity=sensitivity,model_card={k:v for k,v in manifest.items() if k not in ['coefficients','training_item_scale']})
 base_report['gates']['AC12']={'status':'pass_limited_predictive_scope','reason':'Frozen chronological known-item study with both baselines, compact lag/calendar candidate, validation-only tuning, untouched test metrics, dependence-aware comparisons, slices and sensitivity. No observed-business-utility or real alert-validity claim.'};base_report['alert_evaluation']={'status':'unsupported_observed_labels','reason':'Sales-only ledger has no actual shortage event/window labels, stock state or feasible warning lead time; real false-positive/false-negative/precision/recall claims unavailable. Simulated labels must be separately identified.'}
 base_report['resource_measurement']={'wall_seconds':round(time.monotonic()-t,3),'peak_rss_mb':round(resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024,1),'cpu_threads':1,'GPU_used':False,'python':platform.python_version(),'numpy':np.__version__};write(ROOT/'artifacts/benchmark-report.v1.json',base_report)
 # small immutable illustrative forecast, explicitly external namespace
 i=0;origin=n-1;small={'schema_version':'dormathon.forecast.v1','org_id':'external_uci_online_retail_ii','brand_scope':base_report['brand_scope'],'scenarioDataMode':'EXTERNAL_BENCHMARK','status':'ok','delivery_mode':'precomputed','item_id':'uci_sku_'+str(items[i]),'target_definition':base_report['target_definition'],'knowledge_mode':'retrospective_transaction_time_assumption','knowledge_as_of':str(dates[-1])+'T23:59:59','world_time':str(dates[-1]),'training_cutoff':split['train_end'] if selected=='ridge_lag_calendar' else str(dates[-1]),'population_eligibility_cutoff':split['train_end'],'feature_information_cutoff':str(dates[-1]),'forecast_origin':str(dates[-1]),'assumption_set_id':'uci_ledger_observability.v1','model_version':VERSION+':'+selected,'prediction_type':'point','uncertainty':None,'uncertainty_reason':'Point-only study; no calibrated prediction interval','provenance_refs':['uci-online-retail-ii:sha256:'+p['source']['raw_file_sha256']],'input_refs':[split['configuration_sha256']],'data_revision':p['source']['raw_file_sha256'],'request_id':'uci-example-seven-day-v1','warnings':base_report['warnings']+base_report['limitations']}
 yy=y[i:i+1];dd=np.array([str(x) for x in dates]+[(dt.date.fromisoformat(str(dates[-1]))+dt.timedelta(days=h)).isoformat() for h in range(1,8)]);vec=baseline(yy,[origin])[selected][0,0] if selected!='ridge_lag_calendar' else ridge(yy,[origin],means[i:i+1],dd,coef)[0,0];small['forecasts']=[{'date':str(dd[n+h]),'horizon':h+1,'predicted_units':float(v)} for h,v in enumerate(vec)];write(ROOT/'artifacts/example-forecast.v1.json',small);print('EVALUATION_COMPLETE',json.dumps({'selected_model':selected,'models':{k:{'validation_WAPE':v['validation']['WAPE'],'test_MAE':v['test']['MAE_units'],'test_WAPE':v['test']['WAPE']} for k,v in models.items()},'resource':base_report['resource_measurement']}),flush=True)
if __name__=='__main__':run()
